'use client'

import gsap from 'gsap'
import { createTransition } from './transition-core'
import './transitions.css'

/**
 * Slate.
 *
 * A clapperboard rises into frame from the bottom, stick open, and covers the
 * page. The stick claps shut — that is the moment the screen is fully covered
 * and the route swaps behind it. The stick lifts again and the new page shows
 * in the gap it leaves above the board, then the whole slate is pulled down
 * out of frame. Nothing fades; every reveal is a piece of board moving.
 *
 * The motion is written as a hand would do it. The slate comes into shot
 * off-square — leaning away, rolled a few degrees, a touch small — and
 * squares up as it arrives, a hair high, then settles. Flat and full-width
 * from the first frame it read as a wipe; the lean and roll are what make it
 * a thing being held over the page. The stick falls under gravity and
 * rebounds once, the slate dips on impact and the hand absorbs it, the lift
 * is quick with a soft stop, and the pull-out takes it away the same way it
 * came, slow then gone.
 *
 *   // app/layout.tsx
 *   <SlateTransition>{children}</SlateTransition>
 */
export type SlateOptions = {
  /** Degrees the stick opens. */
  angle: number
  /** Height of the stick as a share of the viewport height, in vh. */
  stick: number
  /** Which end the stick pivots on. */
  hinge: 'left' | 'right'
  /** Seconds the slate takes to rise into frame, and to be pulled out. */
  duration: number
  /** Seconds the stick stays shut after the route swaps, before it lifts. */
  hold: number
  /** How far the slate drops after the clap, in vh, bringing the stick's top edge into frame. 0 keeps it flush. */
  settle: number
  /** Sideways travel on the way in and out, in vw, from the hinge side — the arc of the hand. 0 is straight up and down. */
  drift: number
  /** Jolt of the slate at the clap, in px. 0 for none. */
  shake: number
  /** Multiplies the whole timeline. Above 1 is faster. */
  speed: number
  /** Board and stripe colours. "custom" applies no preset, leaving --slate-board and --slate-stripe to you. */
  palette: 'ink' | 'chalk' | 'custom'
}

const DEFAULTS: SlateOptions = {
  angle: 20,
  stick: 12,
  hinge: 'left',
  duration: 0.5,
  hold: 0.08,
  settle: 7,
  drift: 5,
  shake: 2,
  speed: 1,
  palette: 'ink',
}

const parts = (overlay: HTMLDivElement) => ({
  rig: overlay.querySelector<HTMLElement>('.slate-rig'),
  stick: overlay.querySelector<HTMLElement>('.slate-stick'),
})

/** Open is a lift of the far end: anticlockwise on a left hinge, clockwise on a right one. */
const open = (o: SlateOptions) => (o.hinge === 'left' ? -o.angle : o.angle)

/** Parked below the frame and hidden. */
const park = (rig: HTMLElement) => gsap.set(rig, { yPercent: 100, visibility: 'hidden' })

/**
 * Where the slate sits for the clap, as a yPercent: a hair above flush, so the
 * impact dip lands at flush rather than below it and the top edge of the stick
 * never uncovers the page while the screen is meant to be covered.
 */
const SEAT = -0.8

/**
 * How far below the frame the slate has to be for all of it to be out of
 * shot, as a yPercent. One screen height clears the board, but the open stick
 * stands well above the board at its far end — a screen width times the sine
 * of the angle — so the whole thing has to start that much lower, and the tip
 * of the stick is the first thing to come into view.
 */
const clearance = (rig: HTMLElement, o: SlateOptions) => {
  const w = rig.clientWidth
  const h = rig.clientHeight
  const tip = w * Math.sin((o.angle * Math.PI) / 180) + (o.stick / 100) * h
  return 100 + (tip / h) * 100
}

/**
 * The off-square pose the slate holds while it is in the hand: leaning away at
 * the top, rolled towards the hinge side, and a little small. Pivoting at the
 * bottom edge, where the hand is. Everything here is zero once it has arrived.
 */
const held = (o: SlateOptions, roll: number) => ({
  rotationX: 12,
  rotation: o.hinge === 'left' ? -roll : roll,
  xPercent: o.hinge === 'left' ? -o.drift : o.drift,
  scale: 0.94,
})
const SQUARE = { rotationX: 0, rotation: 0, xPercent: 0, scale: 1 }

export const SlateTransition = createTransition<SlateOptions>({
  timeout: 6000,
  defaults: DEFAULTS,

  overlay: (o) => (
    <div
      className={[
        'slate',
        `slate-hinge-${o.hinge}`,
        o.palette === 'custom' ? '' : `slate-${o.palette}`,
      ].join(' ')}
      style={{ '--slate-stick': `${o.stick}vh` } as React.CSSProperties}
    >
      <div className="slate-rig">
        <div className="slate-stick" />
        <div className="slate-board">
          <div className="slate-lip" />
        </div>
      </div>
    </div>
  ),

  setup: (overlay, options) => {
    const { rig, stick } = parts(overlay)
    if (rig) park(rig)
    if (stick) gsap.set(stick, { rotation: open(options) })
  },

  leave: ({ overlay, options: o, done }) => {
    const { rig, stick } = parts(overlay)
    if (!rig || !stick) {
      done()
      return
    }
    const d = o.duration
    const tl = gsap.timeline({ onComplete: done })

    gsap.set(rig, {
      visibility: 'visible',
      yPercent: clearance(rig, o),
      transformPerspective: 800,
      transformOrigin: '50% 100%',
      ...held(o, 5),
    })
    gsap.set(stick, { rotation: open(o) })

    // Rise: a reach, bell-shaped velocity, squaring up on the way, a hair too
    // high, then set down.
    tl.to(rig, { yPercent: SEAT - 1.5, ...SQUARE, duration: d, ease: 'power2.inOut' })
    tl.to(rig, { yPercent: SEAT, duration: 0.14, ease: 'power2.inOut' })

    // Clap: gravity and a flick of the wrist, then one rebound. It begins while
    // the slate is still setting down, so the arrival and the clap are one gesture.
    tl.to(stick, { rotation: 0, duration: 0.15, ease: 'power3.in' }, '-=0.08')
    tl.addLabel('impact')
    tl.to(stick, { rotation: open(o) * 0.07, duration: 0.05, ease: 'power1.out' })
    tl.to(stick, { rotation: 0, duration: 0.07, ease: 'power1.in' })

    // The hand takes the hit: the whole slate dips and comes back, with a
    // sideways jolt that dies out in a few frames.
    tl.to(rig, { yPercent: 0, duration: 0.05, ease: 'power2.out' }, 'impact')
    tl.to(rig, { yPercent: SEAT, duration: 0.22, ease: 'power2.out' }, 'impact+=0.05')
    if (o.shake) {
      const j = o.shake
      tl.to(rig, { x: j, duration: 0.03, ease: 'power1.out' }, 'impact')
      tl.to(rig, { x: -j * 0.6, duration: 0.04, ease: 'power1.inOut' }, 'impact+=0.03')
      tl.to(rig, { x: j * 0.3, duration: 0.04, ease: 'power1.inOut' }, 'impact+=0.07')
      tl.to(rig, { x: 0, duration: 0.05, ease: 'power1.out' }, 'impact+=0.11')
    }

    tl.timeScale(o.speed)
    return () => tl.kill()
  },

  enter: ({ overlay, options: o, done }) => {
    const { rig, stick } = parts(overlay)
    if (!rig || !stick) {
      done()
      return
    }
    const d = o.duration
    const tl = gsap.timeline({
      onComplete: () => {
        park(rig)
        done()
      },
    })

    gsap.set(rig, {
      visibility: 'visible',
      yPercent: SEAT,
      x: 0,
      transformPerspective: 800,
      transformOrigin: '50% 100%',
      ...SQUARE,
    })
    gsap.set(stick, { rotation: 0 })

    // The hand relaxes after the hit: the slate settles down a few vh and the
    // top edge of the stick comes into frame, with the new page above it.
    tl.to(rig, { yPercent: o.settle, duration: 0.24, ease: 'power2.out' }, o.hold)

    // Lift: the thumb flicks it open, soft stop with a touch of overshoot.
    tl.to(stick, { rotation: open(o), duration: 0.3, ease: 'back.out(1.5)' }, o.hold + 0.1)

    // Pull-out, once it has settled and while the stick is still lifting: it
    // drops, rolls the other way and leans off as the hand takes it, slow
    // then away.
    tl.to(rig, { yPercent: clearance(rig, o), ...held(o, -4), duration: d, ease: 'power3.in' }, o.hold + 0.3)

    tl.timeScale(o.speed)
    return () => tl.kill()
  },
})

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef, type ReactNode } from 'react'

/** Passed to every phase. Query your own nodes out of `overlay`. */
export type TransitionContext<O> = {
  overlay: HTMLDivElement
  /** Whatever the component was given, merged over the config defaults. */
  options: O
  /** Call when the animation is finished. The navigation waits for this. */
  done: () => void
}

/** A phase may return a cleanup function, called if the phase is interrupted. */
export type Phase<O> = (ctx: TransitionContext<O>) => void | (() => void)

export type TransitionConfig<O> = {
  /**
   * Markup that covers the screen. A function when the markup itself depends on
   * the options; otherwise rendered once and reused for every navigation.
   */
  overlay: ReactNode | ((options: O) => ReactNode)
  /** Values a consumer may override as props. */
  defaults: O
  /** Runs once after mount — measure paths, set starting state. */
  setup?: (overlay: HTMLDivElement, options: O) => void
  /** Plays before the route changes. */
  leave: Phase<O>
  /** Plays after the route changes. */
  enter: Phase<O>
  /**
   * Failsafe. If a phase never calls done() the navigation continues anyway,
   * so a broken animation can never trap someone behind an opaque overlay.
   */
  timeout?: number
}

const DEFAULT_TIMEOUT = 4000

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Turns a transition config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Engine-agnostic: the phases can use GSAP, Motion, or raw WAAPI. The core only
 * cares that `done()` eventually gets called.
 */
export function createTransition<O extends object>(config: TransitionConfig<O>) {
  const timeout = config.timeout ?? DEFAULT_TIMEOUT

  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const ref = useRef<HTMLDivElement>(null)
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O

    // Phases read this rather than closing over a stale render's options.
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      if (ref.current) config.setup?.(ref.current, latest.current)
    }, [])

    const run = (phase: Phase<O>) => (next: () => void) => {
      const overlay = ref.current

      // No overlay yet, or the user asked for less motion — navigate straight through.
      if (!overlay || prefersReducedMotion()) {
        next()
        return
      }

      let settled = false
      const done = () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        next()
      }
      const timer = setTimeout(() => {
        console.warn(`[transition] phase exceeded ${timeout}ms, continuing`)
        done()
      }, timeout)

      let cleanup: void | (() => void)
      try {
        cleanup = phase({ overlay, options: latest.current, done })
      } catch (error) {
        console.error('[transition] phase threw, continuing', error)
        done()
      }

      return () => {
        clearTimeout(timer)
        settled = true
        cleanup?.()
      }
    }

    return (
      <TransitionRouter auto leave={run(config.leave)} enter={run(config.enter)}>
        <div ref={ref} className="transition-overlay" aria-hidden>
          {typeof config.overlay === 'function' ? config.overlay(options) : config.overlay}
        </div>
        {children}
      </TransitionRouter>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

/* ---------- crayon ---------- */

/*
 * Scoped to crayon rather than every svg in an overlay. As `.transition-overlay
 * svg` it outranked any single class a later transition could put on its own
 * svg, so it silently forced them all to full size — the zipper only escaped
 * because it sets its own width and height.
 */
.crayon svg {
  display: block;
  width: 100%;
  height: 100%;
}

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

/*
 * The fire is its own colour, not the pages'. The outgoing page is masked away
 * inside the burn front, the incoming page is masked to show only inside a
 * slightly smaller front, and this ramp sits behind both — so what you see in
 * the gap between them is the fire itself.
 *
 * The ramp is anchored to the band rather than the origin. Anchored to the
 * origin, the visible annulus samples the cold end of the gradient once the
 * front is halfway out, and the fire goes dull.
 */
:root,
.burn-ember {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
}

/* Magnesium burns brilliant white and almost colourless — the point of it is
   that there is no hue, so this stays neutral all the way down. */
.burn-magnesium {
  --burn-core: #ffffff;
  --burn-hot: #f6f7f8;
  --burn-mid: #a9aeb4;
  --burn-edge: #34383d;
}

.burn-cold {
  --burn-core: #ddf5ff;
  --burn-hot: #33c9ff;
  --burn-mid: #0a5fd4;
  --burn-edge: #04123f;
}

.burn-toxic {
  --burn-core: #f4ffd9;
  --burn-hot: #c6ff3d;
  --burn-mid: #46b81a;
  --burn-edge: #0d3a0a;
}

.vt-film-burn::view-transition-group(root) {
  animation: none;
  background:
    radial-gradient(
      circle at var(--burn-x, 50%) var(--burn-y, 50%),
      var(--burn-core) calc(var(--burn-cut, 0px) - var(--burn-band, 64px)),
      var(--burn-hot) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.68),
      var(--burn-mid) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.3),
      var(--burn-edge) var(--burn-cut, 0px),
      var(--burn-edge) 100%
    );
}

.vt-film-burn::view-transition-image-pair(root) {
  isolation: auto;
}

/* The browser stacks the incoming snapshot above the outgoing one, so the
   outgoing page has to be lifted for its mask to read as a hole rather than as
   nothing at all. */
.vt-film-burn::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 1;
  mask: url(#burn-mask-new);
  -webkit-mask: url(#burn-mask-new);
}

.vt-film-burn::view-transition-old(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 2;
  mask: url(#burn-mask-old);
  -webkit-mask: url(#burn-mask-old);
}

/* ---------- riser ---------- */

/*
 * Nothing here is driven from JavaScript. The outgoing page is pushed back and
 * dimmed, the incoming page is unmasked over it, and the browser runs both off
 * the stylesheet — which is why this one needs no dependencies at all.
 */
.vt-riser::view-transition-group(root) {
  animation: none;
}

.vt-riser::view-transition-image-pair(root) {
  isolation: auto;
}

/*
 * Origin at the arriving edge, not the centre. Scaling about the centre pulls
 * the outgoing page away from that edge, so it reads as sliding off rather than
 * settling behind. Anchored to the edge it recedes into the space the incoming
 * page is about to occupy, and stays visible above it the whole way.
 */
.vt-riser::view-transition-old(root) {
  animation: riser-recede var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 1;
  transform-origin: var(--riser-origin, 50% 0%);
}

/*
 * The incoming page slides in as a card rather than being clipped into view. A
 * clip reveal has no edge and casts nothing, so there is no cue that one page
 * is above the other — the shadow is what actually sells the layering.
 */
.vt-riser::view-transition-new(root) {
  animation: riser-arrive var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 2;
  box-shadow: var(--riser-shadow, 0 -24px 60px rgba(0, 0, 0, 0.45));
}

/* The tilt is what makes it read as depth rather than a shrink — the page
   leans away from you as it drops back. */
/*
 * Perspective distance matters as much as the angle. At 1400px a 6deg lean
 * narrows the far edge by about 6%, which reads as nothing at all; 900px and
 * 14deg takes it to 80%, which is unmistakably a page leaning away.
 */
@keyframes riser-recede {
  to {
    opacity: var(--riser-dim, 0.35);
    transform: perspective(var(--riser-perspective, 800px))
      translate3d(var(--riser-out-x, 0), var(--riser-out-y, -8vh), 0)
      rotateX(var(--riser-tilt-x, 18deg)) rotateY(var(--riser-tilt-y, 0deg))
      scale(var(--riser-depth, 0.82));
  }
}

@keyframes riser-arrive {
  from {
    transform: translate3d(var(--riser-in-x, 0), var(--riser-in-y, 100%), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/* The incoming page is unmasked from the edge it arrives at, and the outgoing
   page recedes the opposite way, so the two read as one movement. */
.riser-up {
  --riser-in-y: 100%;
  --riser-in-x: 0;
  --riser-shadow: 0 -24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 0%;
  --riser-out-y: calc(var(--riser-travel, 8vh) * -1);
  --riser-out-x: 0;
  --riser-tilt-x: var(--riser-tilt, 18deg);
  --riser-tilt-y: 0deg;
}

.riser-down {
  --riser-in-y: -100%;
  --riser-in-x: 0;
  --riser-shadow: 0 24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 100%;
  --riser-out-y: var(--riser-travel, 8vh);
  --riser-out-x: 0;
  --riser-tilt-x: calc(var(--riser-tilt, 18deg) * -1);
  --riser-tilt-y: 0deg;
}

.riser-left {
  --riser-in-y: 0;
  --riser-in-x: 100%;
  --riser-shadow: -24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 0% 50%;
  --riser-out-x: calc(var(--riser-travel-x, 8vw) * -1);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: calc(var(--riser-tilt, 18deg) * -1);
}

.riser-right {
  --riser-in-y: 0;
  --riser-in-x: -100%;
  --riser-shadow: 24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 100% 50%;
  --riser-out-x: var(--riser-travel-x, 8vw);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: var(--riser-tilt, 18deg);
}

@media (prefers-reduced-motion: reduce) {
  .vt-riser::view-transition-old(root),
  .vt-riser::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- push ---------- */

/*
 * Both pages travel the same direction, the outgoing one slower, so it is
 * overtaken rather than shoved off. Nothing but a transform on each snapshot
 * and a brightness on the one being covered — no JavaScript touches a frame.
 */

:root {
  /* Material 3's emphasized curve: leaves quickly, arrives gently. */
  --push-ease: cubic-bezier(0.2, 0, 0, 1);
}

.vt-push::view-transition-group(root) {
  animation: none;
}

.vt-push::view-transition-image-pair(root) {
  isolation: auto;
}

.vt-push::view-transition-old(root) {
  animation: push-recede var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 1;
}

.vt-push::view-transition-new(root) {
  animation: push-arrive var(--vt-duration, 0.42s) var(--push-ease) both;
  mix-blend-mode: normal;
  z-index: 2;
  /* Reads the seam between the two pages while they overlap. */
  box-shadow: var(--push-shadow, -18px 0 48px rgba(0, 0, 0, 0.34));
}

/*
 * brightness rather than opacity: the outgoing page has the incoming one
 * already rendered behind it, so fading it out would cross-dissolve the two
 * instead of darkening one.
 */
@keyframes push-recede {
  to {
    transform: translate3d(var(--push-out-x, 0), var(--push-out-y, 0), 0);
    filter: brightness(var(--push-dim, 0.78));
  }
}

@keyframes push-arrive {
  from {
    transform: translate3d(var(--push-in-x, 100%), var(--push-in-y, 0), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

.push-left {
  --push-in-x: 100%;
  --push-in-y: 0;
  --push-out-x: calc(var(--push-parallax, 28%) * -1);
  --push-out-y: 0;
  --push-shadow: -18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-right {
  --push-in-x: -100%;
  --push-in-y: 0;
  --push-out-x: var(--push-parallax, 28%);
  --push-out-y: 0;
  --push-shadow: 18px 0 48px rgba(0, 0, 0, 0.34);
}

.push-up {
  --push-in-x: 0;
  --push-in-y: 100%;
  --push-out-x: 0;
  --push-out-y: calc(var(--push-parallax, 28%) * -1);
  --push-shadow: 0 -18px 48px rgba(0, 0, 0, 0.34);
}

.push-down {
  --push-in-x: 0;
  --push-in-y: -100%;
  --push-out-x: 0;
  --push-out-y: var(--push-parallax, 28%);
  --push-shadow: 0 18px 48px rgba(0, 0, 0, 0.34);
}

@media (prefers-reduced-motion: reduce) {
  .vt-push::view-transition-old(root),
  .vt-push::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- concertina ---------- */

/*
 * The slats are laid out at their collapsed size and scaled up to cover, so
 * nothing here animates width or height — a strip of forty slats re-laying out
 * every frame is the one thing that would make this expensive.
 */

:root {
  --cc-ground: #0d0d0f;
  --cc-slat: #f6f4ef;
}

.cc-stage {
  position: absolute;
  inset: 0;
  overflow: clip;
}

.cc-ground {
  position: absolute;
  inset: 0;
  background: var(--cc-ground);
}

/*
 * The row runs in a centred window rather than edge to edge. Two things follow
 * from that: slats clip in and out at its sides as the row slides, and the arcs
 * span the window too — the same curve across a narrower span is much steeper
 * at its ends, which is what slants the outermost slats.
 */
.cc-window {
  position: absolute;
  top: 0;
  bottom: 0;
  /* left and width are set in whole pixels from the component — see sizeWindow. */
  left: 0;
  width: var(--cc-window, 60vw);
  overflow: hidden;
}

.cc-strip {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cc-slat {
  flex: 0 0 auto;
  /* So the one standing in for the page can be raised over its neighbours. */
  position: relative;
  width: var(--cc-slat-w, 3vw);
  height: var(--cc-slat-h, 45vh);
  margin: 0 var(--cc-gap, 0.5vw);
  background: var(--cc-slat);
}

/*
 * The bow. Two arcs in the ground colour lying over a row of flat slats — the
 * edge slats read as taller than the middle ones because each is bitten into by
 * a different part of the curve. preserveAspectRatio is none on purpose: a
 * quadratic stays a quadratic under a non-uniform scale, so the arc survives any
 * viewport shape and `bow` alone decides how deep it goes.
 */
.cc-arc {
  position: absolute;
  left: 0;
  width: 100%;
  height: 50%;
  display: block;
  fill: var(--cc-ground);
}

.cc-arc.is-top {
  top: 0;
}

.cc-arc.is-bottom {
  bottom: 0;
}

.cc-mono {
  --cc-ground: #0d0d0f;
  --cc-slat: #f6f4ef;
}

.cc-inverse {
  --cc-ground: #f2efe8;
  --cc-slat: #17171a;
}

.cc-ember {
  --cc-ground: #170a04;
  --cc-slat: #ff9d3c;
}

.cc-pine {
  --cc-ground: #0b1a16;
  --cc-slat: #7fd0b4;
}

/* ---------- dither ---------- */

:root {
  --dither-ground: #0a0a0a;
}

.dither {
  position: absolute;
  inset: 0;
  overflow: clip;
}

/* Scoped to its own canvas — see the note on `.crayon svg`. */
.dither canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.dither-ink       { --dither-ground: #0a0a0a; }
.dither-paper     { --dither-ground: #f2efe8; }
.dither-blueprint { --dither-ground: #1f4470; }
.dither-ember     { --dither-ground: #170a04; }

/* ---------- slate ---------- */

/*
 * Three pieces and nothing but transforms: the rig rises and is pulled out,
 * the stick rotates on its hinge, the board just rides along. The board
 * overruns the bottom so the rise's overshoot never shows an edge.
 */

:root {
  --slate-board: #141414;
  --slate-stripe: #f2efe8;
  --slate-stick: 12vh;
}

.slate {
  position: absolute;
  inset: 0;
  overflow: clip;
}

.slate-rig {
  position: absolute;
  inset: 0;
  will-change: transform;
}

.slate-stick {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--slate-stick);
  transform-origin: 0% 100%;
  will-change: transform;
  /* Lies on the board when shut; hangs over it when open. */
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);
}

/* A highlight along the top and a dark under-edge: a bar with thickness, not a painted band. */
.slate-stick::before,
.slate-stick::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
}

.slate-stick::before {
  top: 0;
  height: 2px;
  background: rgba(255, 255, 255, 0.28);
}

.slate-stick::after {
  bottom: 0;
  height: 3px;
  background: rgba(0, 0, 0, 0.4);
}

.slate-hinge-right .slate-stick {
  transform-origin: 100% 100%;
}

.slate-board {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--slate-stick);
  bottom: -30vh;
  background: var(--slate-board);
  /* The board sits above the page: a shadow into the gap, and one all round
     for while it is off-square on the way in and out. */
  box-shadow:
    0 -6px 24px rgba(0, 0, 0, 0.35),
    0 0 60px rgba(0, 0, 0, 0.3);
}

.slate-lip {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: var(--slate-stick);
}

/* Stripes lean opposite ways on the two halves, meeting as chevrons at the seam. */
.slate-stick {
  background: repeating-linear-gradient(
    -60deg,
    var(--slate-stripe) 0 calc(var(--slate-stick) * 0.5),
    var(--slate-board) 0 calc(var(--slate-stick) * 1)
  );
}

.slate-lip {
  background: repeating-linear-gradient(
    60deg,
    var(--slate-stripe) 0 calc(var(--slate-stick) * 0.5),
    var(--slate-board) 0 calc(var(--slate-stick) * 1)
  );
}

.slate-ink   { --slate-board: #141414; --slate-stripe: #f2efe8; }
.slate-chalk { --slate-board: #f2efe8; --slate-stripe: #141414; }

@media (prefers-reduced-motion: reduce) {
  .slate { display: none }
}
